   507  /// An immutable JavaScript primitive string consisting of length and a pointer
   508  /// to characters (either char or char16). The storage uses std::string or
   509  /// std::u16string, and the object's finalizer deallocates the storage.
   510  /// Note: while StringPrimitive extends VariableSizeRuntimeCell, these subtypes
   511  /// are not actually variable-sized: we indicate that they are fixed-size in the
   512  /// metadata.
   513  template <typename T>
   514  class ExternalStringPrimitive final : public SymbolStringPrimitive {
   515    friend class IdentifierTable;
   516    friend class StringBuilder;
   517    friend class StringPrimitive;
   518    // BufferedStringPrimitive uses this class for storage and needs to be able
   519    // to append to the contents.
   520    template <typename U>
   521    friend class BufferedStringPrimitive;
   522    friend PseudoHandle<StringPrimitive> internalConcatStringPrimitives(
   523        Runtime *runtime,
   524        Handle<StringPrimitive> leftHnd,
   525        Handle<StringPrimitive> rightHnd);
   526
   527  #ifdef UNIT_TEST
   528    // Test version needs access.
   529    friend class ExtStringForTest;
   530  #endif
   531
   532    using Ref = llvh::ArrayRef<T>;
   533    using StdString = std::basic_string<T>;
   534    using CopyableStdString = CopyableBasicString<T>;
   535
   536    /// \return the cell kind for this string.
   537    static constexpr CellKind getCellKind() {
   538      return std::is_same<T, char16_t>::value
   539          ? CellKind::ExternalUTF16StringPrimitiveKind
   540          : CellKind::ExternalASCIIStringPrimitiveKind;
   541    }
   542
   543   public:
   544  #ifdef HERMESVM_SERIALIZE
   545    template <typename>
   546    friend void serializeExternalStringImpl(Serializer &s, const GCCell *cell);
   547
   548    template <typename>
   549    friend void deserializeExternalStringImpl(Deserializer &d);
   550  #endif
   551
   552    static bool classof(const GCCell *cell) {
   553      return cell->getKind() == ExternalStringPrimitive::getCellKind();
   554    }
   555
   556   private:
   557    static const VTable vt;
   558
   559    size_t calcExternalMemorySize() const {
   560      return contents_.capacity() * sizeof(T);
   561    }
