   563    /// Construct an ExternalStringPrimitive from the given string \p contents,
   564    /// non-uniqued.
   565    template <class BasicString>
   566    ExternalStringPrimitive(Runtime *runtime, BasicString &&contents);
   567
   568    /// Destructor deallocates the contents_ string.
   569    ~ExternalStringPrimitive() = default;
   570
   571    /// Transfer ownership of an std::string into a new StringPrim. Throw \c
   572    /// RangeError if the string is longer than \c MAX_STRING_LENGTH characters.
   573    template <class BasicString>
   574    static CallResult<HermesValue> create(Runtime *runtime, BasicString &&str);
   575
   576    /// Like the above, but the created StringPrimitive will be allocated in a
   577    /// "long-lived" area of the heap (if the GC supports that concept).  Note
   578    /// that this applies only to the object proper; the contents array is
   579    /// allocated outside the JS heap in either case.
   580    static CallResult<HermesValue> createLongLived(
   581        Runtime *runtime,
   582        StdString &&str);
   583
   584    /// Create a StringPrim object with a specified capacity \p length in
   585    /// 16-bit characters. Throw \c RangeError if the string is longer than
   586    /// \c MAX_STRING_LENGTH characters. The new string is returned in
   587    /// \c CallResult<HermesValue>. This should only be used by StringBuilder.
   588    static CallResult<HermesValue> create(Runtime *runtime, uint32_t length);
   589
   590    const T *getRawPointer() const {
   591      // C++11 defines this to be valid even if the string is empty.
   592      return &contents_[0];
   593    }
   594
   595    /// In rare cases it is convenient to allocate an object without populating
   596    /// the string contents and then initialize it dynamically. It should not
   597    /// normally be done, but for those rare cases, this method gives access to
   598    /// the writable buffer.
   599    T *getRawPointerForWrite() {
   600      // C++11 defines this to be valid even if the string is empty.
   601      return &contents_[0];
   602    }
