   604    // Finalizer to clean up the malloc'ed string.
   605    static void _finalizeImpl(GCCell *cell, GC *gc);
   606
   607    /// \return the size of the external memory associated with \p cell, which is
   608    /// assumed to be an ExternalStringPrimitive.
   609    static size_t _mallocSizeImpl(GCCell *cell);
