   882  /*static*/ inline Handle<StringPrimitive> StringPrimitive::createNoThrow(
   883      Runtime *runtime,
   884      llvh::StringRef ascii) {
   885    auto strRes = create(runtime, ASCIIRef(ascii.data(), ascii.size()));
   886    if (strRes == ExecutionStatus::EXCEPTION) {
   887      hermes_fatal("String allocation failed");
   888    }
   889    return runtime->makeHandle<StringPrimitive>(*strRes);
   890  }
