   892  inline CallResult<HermesValue>
   893  StringPrimitive::create(Runtime *runtime, uint32_t length, bool asciiNotUTF16) {
   894    static_assert(
   895        EXTERNAL_STRING_THRESHOLD < MAX_STRING_LENGTH,
   896        "External string threshold should be smaller than max string size.");
   897    if (LLVM_LIKELY(!isExternalLength(length))) {
   898      if (asciiNotUTF16) {
   899        return DynamicASCIIStringPrimitive::create(runtime, length);
   900      } else {
   901        return DynamicUTF16StringPrimitive::create(runtime, length);
   902      }
   903    } else {
   904      if (asciiNotUTF16) {
   905        return ExternalStringPrimitive<char>::create(runtime, length);
   906      } else {
   907        return ExternalStringPrimitive<char16_t>::create(runtime, length);
   908      }
   909    }
   910  }
