   971  inline void StringPrimitive::convertToUniqued(hermes::vm::SymbolID uniqueID) {
   972    assert(canBeUniqued() && "StringPrimitive cannot be uniqued");
   973    assert(!isUniqued() && "StringPrimitive is already uniqued");
   974    assert(
   975        uniqueID.isValid() && uniqueID.isUniqued() &&
   976        "uniqueID SymbolID is not valid and uniqued");
   977    this->lengthAndUniquedFlag_ |= LENGTH_FLAG_UNIQUED;
   978    vmcast<SymbolStringPrimitive>(this)->updateUniqueID(uniqueID);
   979  }
